#!/usr/bin/env python3
"""Chicago pass for Mintlify component titles.

Accordion and Step titles are subheads, so they take sentence style. Card and
Tab titles are labels that cite page names, so they take headline style.
"""
import re
import sys
import pathlib

sys.path.insert(0, str(pathlib.Path(__file__).parent))
from chicago import sentence_case, headline_case  # noqa: E402

SENTENCE_TAGS = ("Accordion", "Step")
HEADLINE_TAGS = ("Card", "Tab")
FENCE = re.compile(r"^\s*(```|~~~)")
ATTR = re.compile(r"<(?P<tag>[A-Za-z]+)(?P<pre>[^>]*?)title=\"(?P<val>[^\"]+)\"")


def fix_line(line):
    def sub(m):
        tag, val = m.group("tag"), m.group("val")
        if tag in SENTENCE_TAGS:
            new = sentence_case(val)
        elif tag in HEADLINE_TAGS:
            new = headline_case(val)
        else:
            return m.group(0)
        return m.group(0).replace(f'title="{val}"', f'title="{new}"')

    return ATTR.sub(sub, line)


def process(path, apply=False):
    lines = pathlib.Path(path).read_text().split("\n")
    out, changes, in_fence = [], [], False
    for n, line in enumerate(lines):
        if FENCE.match(line):
            in_fence = not in_fence
            out.append(line)
            continue
        new = line if in_fence else fix_line(line)
        out.append(new)
        if new != line:
            changes.append((n + 1, line.strip(), new.strip()))
    if apply and changes:
        pathlib.Path(path).write_text("\n".join(out))
    return changes


if __name__ == "__main__":
    apply = "--apply" in sys.argv
